public class Refs {
    static class Counter {
        int count;
        Counter(int start) { count = start; }
    }
    static void bump(Counter c) { c.count++; }
    static void replace(Counter c) { c = new Counter(100); c.count++; }

    public static void main(String[] args) {
        Counter a = new Counter(1);
        Counter b = a;                 // copies the reference, not the object
        b.count = 5;
        System.out.println("a.count = " + a.count);
        System.out.println("a == b: " + (a == b));
        Counter c = new Counter(5);
        System.out.println("a == c: " + (a == c));
        bump(a);
        System.out.println("after bump: " + a.count);
        replace(a);
        System.out.println("after replace: " + a.count);
        Counter d = null;
        try { d.count++; } catch (NullPointerException e) { System.out.println("NPE caught"); }
    }
}

