public class Statics {
    static class Account {
        private static int nextId = 1000;           // one copy, shared by all accounts
        private static final double MIN_BALANCE = 0.0;
        private final int id;                       // one copy per account
        private double balance;

        Account(double opening) { this.id = nextId++; this.balance = opening; }

        static int issued() { return nextId - 1000; }   // no 'this' here
        int id() { return id; }
        double balance() { return balance; }
        void withdraw(double amt) {
            if (balance - amt < MIN_BALANCE) throw new IllegalStateException("insufficient funds");
            balance -= amt;
        }
    }

    public static void main(String[] args) {
        Account a = new Account(50), b = new Account(70);
        System.out.println(a.id() + " " + b.id() + " issued=" + Account.issued());
        a.withdraw(20);
        System.out.println(a.balance());
        try { a.withdraw(100); }
        catch (IllegalStateException e) { System.out.println(e.getMessage()); }
    }
}

