import java.util.ArrayList;
import java.util.List;

public class Defensive {
    static final class LeakyShelf {
        private final List<String> books;
        LeakyShelf(List<String> books) { this.books = books; }   // stores the caller's list
        List<String> books() { return books; }                   // hands out the internal list
    }
    static final class SafeShelf {
        private final List<String> books;
        SafeShelf(List<String> books) { this.books = List.copyOf(books); }  // copy in
        List<String> books() { return books; }   // safe: List.copyOf is unmodifiable
    }

    public static void main(String[] args) {
        List<String> src = new ArrayList<>(List.of("Dune", "Emma"));
        LeakyShelf leaky = new LeakyShelf(src);
        src.add("Hacked");
        leaky.books().remove("Dune");
        System.out.println("leaky: " + leaky.books());

        src = new ArrayList<>(List.of("Dune", "Emma"));
        SafeShelf safe = new SafeShelf(src);
        src.add("Hacked");
        System.out.println("safe: " + safe.books());
        try { safe.books().add("x"); }
        catch (UnsupportedOperationException e) {
            System.out.println("UnsupportedOperationException");
        }
    }
}

