import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

public class Equality {
    static class BadPoint {
        final int x, y;
        BadPoint(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            return o instanceof BadPoint p && p.x == x && p.y == y;
        }
        // hashCode NOT overridden: breaks the contract
    }
    static class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point p = (Point) o;
            return x == p.x && y == p.y;
        }
        @Override public int hashCode() { return Objects.hash(x, y); }
        @Override public String toString() { return "Point[" + x + "," + y + "]"; }
    }
    static class MutableKey {
        int id;
        MutableKey(int id) { this.id = id; }
        @Override public boolean equals(Object o) {
            return o instanceof MutableKey k && k.id == id;
        }
        @Override public int hashCode() { return Integer.hashCode(id); }
    }

    public static void main(String[] args) {
        BadPoint p1 = new BadPoint(1, 2), p2 = new BadPoint(1, 2);
        System.out.println("bad equals: " + p1.equals(p2));
        Set<BadPoint> bad = new HashSet<>();
        bad.add(p1);
        System.out.println("bad contains equal point: " + bad.contains(p2));
        Set<Point> good = new HashSet<>();
        good.add(new Point(1, 2));
        System.out.println("good contains equal point: " + good.contains(new Point(1, 2)));
        System.out.println(new Point(3, 4));
        Map<MutableKey, String> m = new HashMap<>();
        MutableKey k = new MutableKey(1);
        m.put(k, "one");
        k.id = 2;
        System.out.println("after mutation: " + m.get(k) + " / "
                + m.get(new MutableKey(1)) + " / size " + m.size());
    }
}

import java.util.Arrays;

public class Cloning {
    static class Team implements Cloneable {
        String name;
        int[] scores;
        Team(String n, int[] s) { name = n; scores = s; }
        @Override public Team clone() {
            try { return (Team) super.clone(); }          // shallow copy
            catch (CloneNotSupportedException e) { throw new AssertionError(e); }
        }
    }
    static class Copyable {
        final String name;
        final int[] scores;
        Copyable(String n, int[] s) { name = n; scores = s.clone(); }
        Copyable(Copyable o) { this(o.name, o.scores); }   // copy constructor: explicit, deep
    }

    public static void main(String[] args) {
        Team a = new Team("A", new int[] {1, 2, 3});
        Team b = a.clone();
        b.scores[0] = 99;
        System.out.println(Arrays.toString(a.scores) + " shared=" + (a.scores == b.scores));
        Copyable c = new Copyable("C", new int[] {1, 2, 3});
        Copyable d = new Copyable(c);
        d.scores[0] = 99;
        System.out.println(Arrays.toString(c.scores));
    }
}

