public class Local {
    interface Greeter { String greet(); }

    static List<Greeter> make() {
        List<Greeter> list = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            final int n = i;                 // copy captured by value
            list.add(() -> "hello " + n);
        }
        return list;
    }

    static int sum(int[] xs) {
        record Pair(int a, int b) {}         // local record
        int total = 0;
        for (int i = 0; i + 1 < xs.length; i++) {
            Pair p = new Pair(xs[i], xs[i + 1]);
            total += p.a() * p.b();
        }
        return total;
    }

    public static void main(String[] args) {
        for (Greeter g : make()) System.out.println(g.greet());
        System.out.println(sum(new int[]{1, 2, 3, 4}));
        class Local1 { int v = 7; }            // local class
        System.out.println(new Local1().v + " " + Local1.class.getName());
    }
}

