import java.util.ArrayList;
import java.util.List;

public class Leak {
    static class Report {
        private final byte[] big = new byte[10_000_000];          // 10 MB

        Runnable usesOuter() {                                    // anonymous, reads Report.this
            return new Runnable() {
                public void run() { System.out.println(big.length); }
            };
        }
        Runnable ignoresOuter() {                                 // anonymous, never touches it
            return new Runnable() {
                public void run() { System.out.println("task"); }
            };
        }
    }

    static void fields(Class<?> c) {
        var fs = c.getDeclaredFields();
        for (var f : fs) System.out.println(c.getName() + " has field " + f.getName());
        if (fs.length == 0) System.out.println(c.getName() + " has no fields");
    }

    public static void main(String[] args) throws Exception {
        Report r = new Report();
        fields(r.usesOuter().getClass());
        fields(r.ignoresOuter().getClass());
        List<Runnable> keep = new ArrayList<>();
        for (int i = 0; i < 20; i++) {
            keep.add(new Report().usesOuter());     // each task keeps its 10 MB Report alive
            System.out.println("kept " + keep.size());
        }
    }
}

