import java.util.Arrays;

public class Planets {
    enum Level {
        LOW(1), MEDIUM(5), HIGH(10);

        private final int weight;
        Level(int weight) { this.weight = weight; }     // implicitly private
        int weight() { return weight; }
        boolean atLeast(Level other) { return compareTo(other) >= 0; }
    }

    enum Op {
        ADD("+") { int apply(int a, int b) { return a + b; } },
        MUL("*") { int apply(int a, int b) { return a * b; } };

        final String symbol;
        Op(String symbol) { this.symbol = symbol; }
        abstract int apply(int a, int b);
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(Level.values()));
        System.out.println(Level.valueOf("HIGH").weight());
        System.out.println(Level.HIGH.ordinal() + " " + Level.HIGH.name());
        System.out.println(Level.HIGH.atLeast(Level.MEDIUM));
        for (Op op : Op.values())
            System.out.println(op + " " + op.symbol + " " + op.apply(6, 7)
                + " " + op.getClass() + " " + op.getDeclaringClass());
        try { Level.valueOf("high"); }
        catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }
        System.out.println(Level.LOW == Level.valueOf("LOW"));
    }
