public class Rec2 {
    record Range(int lo, int hi) {
        Range {
            if (lo > hi) throw new IllegalArgumentException(lo + " > " + hi);
        }
        Range(int single) { this(single, single); }        // non-canonical must delegate
        static final Range EMPTY = new Range(0, 0);        // static fields allowed
        int length() { return hi - lo; }
        static Range of(String s) {
            String[] p = s.split("-");
            return new Range(Integer.parseInt(p[0]), Integer.parseInt(p[1]));
        }
    }
    record Pair<A, B>(A first, B second) {}
    record Line(Pair<Integer,Integer> from, Pair<Integer,Integer> to) {}
    record Person(String name, int age) implements Serializable {}
    record Version(String tag) implements Comparable<Version> {
        public int compareTo(Version o) { return tag.compareTo(o.tag); }
        @Override public String toString() { return "v" + tag; }
    }
    record Named(String name) {
        @Override public String name() { return name.trim(); }      // custom accessor
    }

    public static void main(String[] args) throws Exception {
        System.out.println(new Range(5) + " " + Range.of("2-9").length() + " " + Range.EMPTY);
        System.out.println(new Line(new Pair<>(0, 0), new Pair<>(3, 4)));
        var bos = new ByteArrayOutputStream();
        try (var out = new ObjectOutputStream(bos)) { out.writeObject(new Person("Ana", 30)); }
        try (var in = new ObjectInputStream(new ByteArrayInputStream(bos.toByteArray()))) {
            System.out.println(in.readObject());
        }
        System.out.println(new Version("1.2") + " " + new Named("  x ").name()
            + "|" + new Named("  x "));
        System.out.println(new Pair<>(null, 1).equals(new Pair<>(null, 1)));
        System.out.println(new Pair<>(1.0, 0.0).equals(new Pair<>(1.0, -0.0)));
    }
