import java.util.List;

public class Patterns {
    record Point(int x, int y) {}
    record Line(Point from, Point to) {}

    static String old(Object o) {
        if (o instanceof String) {
            String s = (String) o;            // test, cast, bind: three steps
            return "string of " + s.length();
        }
        return "other";
    }

    static String describe(Object o) {
        if (o instanceof String s && s.length() > 3) return "long string " + s;
        if (!(o instanceof Integer i)) return "not an int: " + o;
        return "int " + (i + 1);                       // i is in scope here
    }

    static String classify(Object o) {
        return switch (o) {
            case null -> "null!";
            case Integer i when i > 100 -> "big int " + i;
            case Integer i -> "int " + i;
            case String s when s.isEmpty() -> "empty string";
            case String s -> "string " + s;
            case Line(Point(var x1, var y1), Point(int x2, int y2)) when x1 == x2
                -> "vertical line";
            case Line(Point a, Point b) -> "line " + a + "->" + b;
            case int[] arr -> "int array of " + arr.length;
            case List<?> l -> "list size " + l.size();
            default -> "something else: " + o.getClass().getSimpleName();
        };
    }

    public static void main(String[] args) {
        System.out.println(old("hello") + " | " + old(5));
        System.out.println(describe("hello") + " | " + describe("hi") + " | " + describe(41));
        Object[] tests = {null, 7, 500, "", "abc", new Line(new Point(1, 1), new Point(1, 9)),
            new Line(new Point(0, 0), new Point(2, 3)), new int[3], List.of(1, 2), 2.5};
        for (Object t : tests) System.out.println(classify(t));
        Object obj = new Line(new Point(1, 2), new Point(3, 4));
        if (obj instanceof Line(Point(var a, var b), Point p2)) System.out.println(a + b + p2.x());
    }
}

