import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Fragile {
    // BAD: inheritance couples us to HashSet's internals
    static class CountingHashSet<E> extends HashSet<E> {
        int added = 0;
        @Override public boolean add(E e) { added++; return super.add(e); }
        @Override public boolean addAll(Collection<? extends E> c) {
            added += c.size();
            return super.addAll(c);
        }
    }

    // GOOD: composition + forwarding
    static class CountingSet<E> {
        private final Set<E> inner = new HashSet<>();
        private int added = 0;
        boolean add(E e) { added++; return inner.add(e); }
        boolean addAll(Collection<? extends E> c) {
            boolean changed = false;
            for (E e : c) changed |= add(e);
            return changed;
        }
        int added() { return added; }
    }

    public static void main(String[] args) {
        CountingHashSet<String> bad = new CountingHashSet<>();
        bad.addAll(List.of("a", "b", "c"));
        System.out.println("inheritance: expected 3, got " + bad.added);
        CountingSet<String> good = new CountingSet<>();
        good.addAll(List.of("a", "b", "c"));
        System.out.println("composition: expected 3, got " + good.added());
    }
}

