public class Solid {
    record Order(String id, double total) {}

    // S: one reason to change each
    interface OrderRepository { void save(Order o); }
    interface Notifier { void send(String message); }

    // D: the service depends on abstractions, receives them through the constructor
    static class OrderService {
        private final OrderRepository repo;
        private final Notifier notifier;
        OrderService(OrderRepository repo, Notifier notifier) {
            this.repo = repo;
            this.notifier = notifier;
        }
        void place(Order o) {
            repo.save(o);
            notifier.send("Order " + o.id() + " placed");
        }
    }

    // O: new discount rules are new classes; the calculator never changes
    interface Discount { double apply(double amount); }
    record Percent(double pct) implements Discount {
        public double apply(double amount) { return amount * (1 - pct / 100); }
    }
    record Flat(double off) implements Discount {
        public double apply(double amount) { return Math.max(0, amount - off); }
    }

    public static void main(String[] args) {
        List<String> log = new ArrayList<>();
        OrderService svc = new OrderService(o -> log.add("saved " + o), log::add);
        svc.place(new Order("A1", 99.5));
        log.forEach(System.out::println);
        for (Discount d : List.of(new Percent(10), new Flat(25), new Flat(500)))
            System.out.println(d + " -> " + d.apply(200));
    }
}

