import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public class Imm {
    // Immutable by the checklist
    static final class Loan {
        private final String member;
        private final LocalDate due;
        private final List<String> notes;
        Loan(String member, LocalDate due, List<String> notes) {
            this.member = member;
            this.due = due;
            this.notes = List.copyOf(notes);          // defensive copy, unmodifiable
        }
        String member() { return member; }
        LocalDate due() { return due; }
        List<String> notes() { return notes; }
        Loan withDue(LocalDate newDue) { return new Loan(member, newDue, notes); }
    }

    // Leaky: record does not copy mutable components
    record LeakyLoan(String member, List<String> notes) {}
    record SafeLoan(String member, List<String> notes) {
        SafeLoan { notes = List.copyOf(notes); }
    }

    public static void main(String[] args) {
        List<String> n = new ArrayList<>(List.of("fragile spine"));
        Loan loan = new Loan("Asha", LocalDate.of(2026, 11, 1), n);
        n.add("late once");
        System.out.println(loan.notes());
        try { loan.notes().add("x"); } catch (UnsupportedOperationException e) {
            System.out.println("UOE");
        }
        Loan later = loan.withDue(LocalDate.of(2026, 11, 15));
        System.out.println(loan.due() + " -> " + later.due());

        List<String> shared = new ArrayList<>(List.of("a"));
        LeakyLoan leaky = new LeakyLoan("Ravi", shared);
        SafeLoan safe = new SafeLoan("Ravi", shared);
        shared.add("b");
        System.out.println(leaky.notes() + " vs " + safe.notes());
        System.out.println(new SafeLoan("Ravi", List.of("a")).equals(safe) + " "
            + (new SafeLoan("Ravi", List.of("a")).hashCode() == safe.hashCode()));
    }
}

